create table app_users (id char(36) primary key, created_at datetime(6) not null, updated_at datetime(6) not null, created_by char(36), updated_by char(36), version bigint not null default 0, email varchar(255) not null unique, name varchar(255) not null, password_hash varchar(255) not null, role varchar(30) not null check(role in ('OWNER','ADMIN','STAFF','ACCOUNTANT')), active boolean not null default true) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_0900_ai_ci;
create table auth_sessions (id char(36) primary key,user_id char(36) not null,expires_at datetime(6) not null,revoked_at datetime(6),created_at datetime(6) not null default current_timestamp(6), foreign key (user_id) references app_users(id)) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_0900_ai_ci;
create table refresh_tokens (id char(36) primary key,session_id char(36) not null,token_hash varchar(64) not null unique,expires_at datetime(6) not null,used_at datetime(6), foreign key (session_id) references auth_sessions(id)) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_0900_ai_ci;
create index refresh_session_idx on refresh_tokens(session_id);
create table clients (id char(36) primary key, created_at datetime(6) not null, updated_at datetime(6) not null, created_by char(36), updated_by char(36), version bigint not null default 0, display_name varchar(255) not null, company_name varchar(255) , contact_person varchar(255) , email varchar(255) , phone varchar(255) , whatsapp varchar(255) , country varchar(255) , city varchar(255) , website varchar(2048) , source varchar(255) , status varchar(255) not null check (status in ('LEAD','PROSPECT','ACTIVE','ON_HOLD','INACTIVE','COMPLETED','LOST')), notes longtext , preferred_currency varchar(3) not null check (preferred_currency in ('USD','ILS','JOD')), tags varchar(1000) , assigned_user_id char(36) , first_contact_date date , client_since_date date ) engine=InnoDB default charset=utf8mb4 collate=utf8mb4_0900_ai_ci;
